from pygments import highlight
from pygments.formatters import Terminal256Formatter
from pygments.lexers import Python3Lexer as Py3Lexer

from .coloring import SolarizedDark


class Sentinel(enum.Enum):
    absent = object()


def bindStaticVariable(name: str, value: Any) -> Callable[[Callable[..., Any]], Callable[..., Any]]:
    def decorator(fn: Callable[..., Any]) -> Callable[..., Any]:
        setattr(fn, name, value)
        return fn

    return decorator


def has_non_ascii_chars(s: str) -> bool:
    return any(ord(char) > 127 for char in s)


@bindStaticVariable("formatter", Terminal256Formatter(style=SolarizedDark))
@bindStaticVariable("lexer", Py3Lexer(ensurenl=False))
def colorize(s: str) -> str:
    self = colorize
    if has_non_ascii_chars(s):
        return s
    return highlight(
        s,
        cast(Py3Lexer, self.lexer),
        cast(Terminal256Formatter, self.formatter),
    )


@contextmanager
def supportTerminalColorsInWindows() -> Generator[None, None, None]:
    if sys.platform.startswith("win"):
        colorama.init()
        try:
            yield
        finally:
            colorama.deinit()
    else:
        yield


def stderrPrint(*args: object) -> None:
    print(*args, file=sys.stderr)


def stdoutPrint(*args: object) -> None:
    print(*args)


def isLiteral(s: str) -> bool:
    try:
        ast.literal_eval(s)
    except Exception:
        return False
    return True


def colorizedStderrPrint(s: str) -> None:
    colored = colorize(s)
    with supportTerminalColorsInWindows():
        stderrPrint(colored)


def colorizedStdoutPrint(s: str) -> None:
    colored = colorize(s)
    with supportTerminalColorsInWindows():
        stdoutPrint(colored)


def safe_pformat(obj: object, *args: Any, **kwargs: Any) -> str:
    def _pformat(extra_kwargs: Optional[dict[str, Any]] = None) -> str:
        final_kwargs = dict(kwargs)
        if extra_kwargs:
            final_kwargs.update(extra_kwargs)
        return pprint.pformat(obj, *args, **final_kwargs)

    try:
        is_flat_list = (
            isinstance(obj, list)
            and not args
            and "width" not in kwargs
            and not any(isinstance(el, (list, tuple, dict, set)) for el in obj)
        )
        if is_flat_list:
            formatted = _pformat({"width": 120})
        else:
            formatted = _pformat(None)
    except TypeError:
        try:
            return _pformat({"sort_dicts": False})
        except TypeError:
            return repr(obj)

    if is_flat_list and isinstance(obj, list) and 13 <= len(obj) <= 35:
        lines = formatted.splitlines()
        if len(lines) > 10:
            one_line = repr(obj)
            if len(one_line) <= 120:
                return one_line

    return formatted


DEFAULT_PREFIX = "ic| "
DEFAULT_LINE_WRAP_WIDTH = 70
DEFAULT_CONTEXT_DELIMITER = "- "
DEFAULT_OUTPUT_FUNCTION = colorizedStderrPrint
DEFAULT_ARG_TO_STRING_FUNCTION = pprint.pformat

NO_SOURCE_AVAILABLE_WARNING_MESSAGE = (
    "Failed to access the underlying source code for analysis. Was ic() "
    "invoked in a REPL (e.g. from the command line), a frozen application "
    "(e.g. packaged with PyInstaller), or did the underlying source code "
    "change during execution?"
)


def callOrValue(obj: Any) -> Any:
    return obj() if callable(obj) else obj


class Source(executing.Source):
    def get_text_with_indentation(self, node: ast.AST) -> str:
        result = self.asttokens().get_text(node)
        if "\n" in result:
            result = " " * node.first_token.start[1] + result  # type: ignore[attr-defined]
            result = dedent(result)
        return result.strip()


def prefixLines(prefix: str, s: str, startAtLine: int = 0) -> List[str]:
    lines = s.splitlines()
    for i in range(startAtLine, len(lines)):
        lines[i] = prefix + lines[i]
    return lines


def prefixFirstLineIndentRemaining(prefix: str, s: str) -> List[str]:
    indent = " " * len(prefix)
    lines = prefixLines(indent, s, startAtLine=1)
    lines[0] = prefix + lines[0]
    return lines


def formatPair(prefix: str, arg: Union[str, Sentinel], value: str) -> str:
    if arg is Sentinel.absent:
        argLines: List[str] = []
        valuePrefix = prefix
    else:
        argLines = prefixFirstLineIndentRemaining(prefix, arg)
        valuePrefix = argLines[-1] + ": "

    looksLikeAString = (value[0] + value[-1]) in ["''", '""']
    if looksLikeAString:
        value = "\n".join(prefixLines(" ", value, startAtLine=1))

    valueLines = prefixFirstLineIndentRemaining(valuePrefix, value)
    lines = argLines[:-1] + valueLines
    return "\n".join(lines)


class _SingleDispatchCallable:
    registry: Any
    register: Callable[[Type[Any]], Callable[..., Any]]
    unregister: Callable[[Type[Any]], None]

    def __call__(self, *_: object) -> str:
        raise NotImplementedError


def singledispatch(func: Callable[..., str]) -> _SingleDispatchCallable:
    dispatched = functools.singledispatch(func)

    assert dispatched.register.__closure__ is not None
    closure = dict(
        zip(dispatched.register.__code__.co_freevars, dispatched.register.__closure__)
    )
    registry = closure["registry"].cell_contents
    dispatch_cache = closure["dispatch_cache"].cell_contents

    def unregister(cls: Type[Any]) -> None:
        del registry[cls]
        dispatch_cache.clear()

    setattr(dispatched, "unregister", unregister)
    return cast(_SingleDispatchCallable, dispatched)


@singledispatch
def argumentToString(obj: object) -> str:
    try:
        s = DEFAULT_ARG_TO_STRING_FUNCTION(obj)
    except TypeError:
        s = safe_pformat(obj)

        s = safe_pformat(obj)
    s = s.replace("\\n", "\n")
    return s


@argumentToString.register(str)
def _argumentToString_str(obj: str) -> str:
    if "\n" in obj:
        return "'''" + obj + "'''"
    return "'" + obj.replace("\\", "\\\\") + "'"


class IceCreamDebugger:
    _pairDelimiter = ", "
    lineWrapWidth = DEFAULT_LINE_WRAP_WIDTH
    contextDelimiter = DEFAULT_CONTEXT_DELIMITER

    def __init__(
        self,
        prefix: Union[str, Callable[[], str]] = DEFAULT_PREFIX,
        outputFunction: Callable[[str], None] = DEFAULT_OUTPUT_FUNCTION,
        argToStringFunction: Union[_SingleDispatchCallable, Callable[[Any], str]] = argumentToString,
        includeContext: bool = False,
        contextAbsPath: bool = False,
    ) -> None:
        self.enabled = True
        self.prefix = prefix
        self.includeContext = includeContext
        self.outputFunction = outputFunction
        self.argToStringFunction = argToStringFunction
        self.contextAbsPath = contextAbsPath

    def __call__(self, *args: object) -> object:
        if self.enabled:
            currentFrame = inspect.currentframe()
            assert currentFrame is not None and currentFrame.f_back is not None
            callFrame = currentFrame.f_back
            self.outputFunction(self._format(callFrame, *args))

        if not args:
            return None
        if len(args) == 1:
            return args[0]
        return args

    def format(self, *args: object) -> str:
        currentFrame = inspect.currentframe()
        assert currentFrame is not None and currentFrame.f_back is not None
        return self._format(currentFrame.f_back, *args)

    def _format(self, callFrame: FrameType, *args: object) -> str:
        prefix = cast(str, callOrValue(self.prefix))
        context = self._formatContext(callFrame)

        if not args:
            return prefix + context + self._formatTime()

        if not self.includeContext:
            context = ""
        return self._formatArgs(callFrame, prefix, context, args)

    def _formatArgs(
        self,
        callFrame: FrameType,
        prefix: str,
        context: str,
        args: Sequence[object],
    ) -> str:
        callNode = Source.executing(callFrame).node
        if callNode is not None:
            assert isinstance(callNode, ast.Call)
            source = cast(Source, Source.for_frame(callFrame))
            sanitizedArgStrs = [
                source.get_text_with_indentation(arg)
                for arg in callNode.args
            ]
        else:
            warnings.warn(
                NO_SOURCE_AVAILABLE_WARNING_MESSAGE,
                category=RuntimeWarning,
                stacklevel=4,
            )
            sanitizedArgStrs = [Sentinel.absent] * len(args)

        pairs = list(zip(sanitizedArgStrs, args))
        return self._constructArgumentOutput(prefix, context, pairs)

    def _constructArgumentOutput(
        self,
        prefix: str,
        context: str,
        pairs: Sequence[Tuple[Union[str, Sentinel], object]],
    ) -> str:
        def argPrefix(arg: str) -> str:
            return f"{arg}: "

        formattedPairs = [(arg, self.argToStringFunction(val)) for arg, val in pairs]
        pairStrs = [
            value if (arg is Sentinel.absent or isLiteral(arg)) else (argPrefix(arg) + value)
            for arg, value in formattedPairs
        ]

        allArgsOnOneLine = self._pairDelimiter.join(pairStrs)
        multilineArgs = len(allArgsOnOneLine.splitlines()) > 1

        contextDelimiter = self.contextDelimiter if context else ""
        allPairs = prefix + context + contextDelimiter + allArgsOnOneLine
        firstLineTooLong = len(allPairs.splitlines()[0]) > self.lineWrapWidth

        if multilineArgs or firstLineTooLong:
            if context:
                lines = [prefix + context] + [
                    formatPair(" " * len(prefix), arg, value)
                    for arg, value in formattedPairs
                ]
            else:
                argLines = [formatPair("", arg, value) for arg, value in formattedPairs]
                lines = prefixFirstLineIndentRemaining(prefix, "\n".join(argLines))
        else:
            lines = [prefix + context + contextDelimiter + allArgsOnOneLine]

        return "\n".join(lines)

    def _formatContext(self, callFrame: FrameType) -> str:
        filename, lineNumber, parentFunction = self._getContext(callFrame)
        if parentFunction != "<module>":
            parentFunction = f"{parentFunction}()"
        return f"{filename}:{lineNumber} in {parentFunction}"

    def _formatTime(self) -> str:
        return " at " + datetime.now().strftime("%H:%M:%S.%f")[:-3]

    def _getContext(self, callFrame: FrameType) -> Tuple[str, int, str]:
        frameInfo = inspect.getframeinfo(callFrame)
        filepath = (realpath if self.contextAbsPath else basename)(frameInfo.filename)
        return filepath, frameInfo.lineno, frameInfo.function

    def enable(self) -> None:
        self.enabled = True

    def disable(self) -> None:
        self.enabled = False

    def use_stdout(self) -> None:
        self.outputFunction = colorizedStdoutPrint

    def use_stderr(self) -> None:
        self.outputFunction = colorizedStderrPrint

    def configureOutput(
        self,
        prefix: Union[str, Callable[[], str], Literal[Sentinel.absent]] = Sentinel.absent,
        outputFunction: Union[Callable[[str], None], Literal[Sentinel.absent]] = Sentinel.absent,
        argToStringFunction: Union[Callable[[Any], str], Literal[Sentinel.absent]] = Sentinel.absent,
        includeContext: Union[bool, Literal[Sentinel.absent]] = Sentinel.absent,
        contextAbsPath: Union[bool, Literal[Sentinel.absent]] = Sentinel.absent,
        lineWrapWidth: Union[int, Literal[Sentinel.absent]] = Sentinel.absent,
    ) -> None:
        noParameterProvided = all(
            value is Sentinel.absent
            for key, value in locals().items()
            if key != "self"
        )
        if noParameterProvided:
            raise TypeError("configureOutput() missing at least one argument")

        if prefix is not Sentinel.absent:
            self.prefix = prefix
        if outputFunction is not Sentinel.absent:
            self.outputFunction = outputFunction
        if argToStringFunction is not Sentinel.absent:
            self.argToStringFunction = argToStringFunction
        if includeContext is not Sentinel.absent:
            self.includeContext = includeContext
        if contextAbsPath is not Sentinel.absent:
            self.contextAbsPath = contextAbsPath
        if lineWrapWidth is not Sentinel.absent:
            self.lineWrapWidth = lineWrapWidth


